public sealed class OrcamentoService : FinanceiroServiceBase, IOrcamentoService
{
    private readonly IOrcamentoRepository _repo; private readonly ILogger<OrcamentoService> _logger;
    public OrcamentoService(IOrcamentoRepository repo, ICurrentTenant tenant, ICurrentUser user, IPermissionService permissions, IAuditService audit, ILogger<OrcamentoService> logger) : base(tenant, user, permissions, audit) { _repo = repo; _logger = logger; }
    public async Task<Result<PagedResult<OrcamentoDespesaResponse>>> ListarDespesasAsync(OrcamentoDespesaFiltro f, CancellationToken ct) { if (!EscopoValido) return EscopoFailure<PagedResult<OrcamentoDespesaResponse>>(); if (!await CanAsync(FinanceiroPermissoes.OrcamentoVisualizar, ct).ConfigureAwait(false)) return Result<PagedResult<OrcamentoDespesaResponse>>.Failure("403"); return Result<PagedResult<OrcamentoDespesaResponse>>.Success(await _repo.ListarDespesasAsync(TenantId, EntidadeId, ExercicioId, f, ct).ConfigureAwait(false)); }
    public async Task<Result<OrcamentoDespesaResponse>> ObterDespesaAsync(long id, CancellationToken ct) { if (!EscopoValido) return EscopoFailure<OrcamentoDespesaResponse>(); if (!await CanAsync(FinanceiroPermissoes.OrcamentoVisualizar, ct).ConfigureAwait(false)) return Result<OrcamentoDespesaResponse>.Failure("403"); var item = await _repo.ObterDespesaAsync(TenantId, EntidadeId, ExercicioId, id, ct).ConfigureAwait(false); return item is null ? Result<OrcamentoDespesaResponse>.Failure("Orçamento não encontrado.") : Result<OrcamentoDespesaResponse>.Success(item); }
    public async Task<Result<long>> CriarDespesaAsync(OrcamentoDespesaCreateRequest r, CancellationToken ct) { if (!EscopoValido) return EscopoFailure<long>(); if (!await CanAsync(FinanceiroPermissoes.OrcamentoCriar, ct).ConfigureAwait(false)) return Result<long>.Failure("403"); if (r.DotacaoInicial < 0m) return Result<long>.Failure("Dotação inicial não pode ser negativa."); try { var id = await _repo.CriarDespesaAsync(TenantId, EntidadeId, ExercicioId, r, UsuarioId, ct).ConfigureAwait(false); await Audit.RegistrarAsync("financeiro", "CRIAR_ORCAMENTO_DESPESA", "sigov.orcamento_despesa", id.ToString(System.Globalization.CultureInfo.InvariantCulture), null, r, ct).ConfigureAwait(false); return Result<long>.Success(id); } catch (Exception ex) { _logger.LogError(ex, "Erro ao criar orçamento da despesa."); return Result<long>.Failure("Erro ao criar orçamento da despesa."); } }
    public async Task<Result> AtualizarDespesaAsync(long id, OrcamentoDespesaUpdateRequest r, CancellationToken ct) { if (!EscopoValido) return EscopoFailure(); if (!await CanAsync(FinanceiroPermissoes.OrcamentoEditar, ct).ConfigureAwait(false)) return Result.Failure("403"); await _repo.AtualizarDespesaAsync(TenantId, EntidadeId, ExercicioId, id, r, UsuarioId, ct).ConfigureAwait(false); return Result.Success(); }
    public async Task<Result> MovimentarDespesaAsync(long id, MovimentacaoOrcamentariaRequest r, CancellationToken ct) { if (!EscopoValido) return EscopoFailure(); if (!await CanAsync(FinanceiroPermissoes.OrcamentoMovimentar, ct).ConfigureAwait(false)) return Result.Failure("403"); try { await _repo.MovimentarDespesaAsync(TenantId, EntidadeId, ExercicioId, id, r, UsuarioId, ct).ConfigureAwait(false); await Audit.RegistrarAsync("financeiro", "ORCAMENTO_MOVIMENTADO", "sigov.orcamento_movimentacao", id.ToString(System.Globalization.CultureInfo.InvariantCulture), null, r, ct).ConfigureAwait(false); return Result.Success(); } catch (Exception ex) { _logger.LogError(ex, "Erro ao movimentar orçamento."); return Result.Failure(ex.Message.StartsWith("409:") || ex.Message.StartsWith("Não") ? ex.Message : "Erro ao movimentar orçamento."); } }
    public async Task<Result<PagedResult<OrcamentoReceitaResponse>>> ListarReceitasAsync(OrcamentoReceitaFiltro f, CancellationToken ct) { if (!EscopoValido) return EscopoFailure<PagedResult<OrcamentoReceitaResponse>>(); if (!await CanAsync(FinanceiroPermissoes.OrcamentoVisualizar, ct).ConfigureAwait(false)) return Result<PagedResult<OrcamentoReceitaResponse>>.Failure("403"); return Result<PagedResult<OrcamentoReceitaResponse>>.Success(await _repo.ListarReceitasAsync(TenantId, EntidadeId, ExercicioId, f, ct).ConfigureAwait(false)); }
    public async Task<Result<OrcamentoReceitaResponse>> ObterReceitaAsync(long id, CancellationToken ct) { if (!EscopoValido) return EscopoFailure<OrcamentoReceitaResponse>(); if (!await CanAsync(FinanceiroPermissoes.OrcamentoVisualizar, ct).ConfigureAwait(false)) return Result<OrcamentoReceitaResponse>.Failure("403"); var item = await _repo.ObterReceitaAsync(TenantId, EntidadeId, ExercicioId, id, ct).ConfigureAwait(false); return item is null ? Result<OrcamentoReceitaResponse>.Failure("Orçamento não encontrado.") : Result<OrcamentoReceitaResponse>.Success(item); }
    public async Task<Result<long>> CriarReceitaAsync(OrcamentoReceitaCreateRequest r, CancellationToken ct) { if (!EscopoValido) return EscopoFailure<long>(); if (!await CanAsync(FinanceiroPermissoes.OrcamentoCriar, ct).ConfigureAwait(false)) return Result<long>.Failure("403"); var id = await _repo.CriarReceitaAsync(TenantId, EntidadeId, ExercicioId, r, UsuarioId, ct).ConfigureAwait(false); return Result<long>.Success(id); }
    public async Task<Result> AtualizarReceitaAsync(long id, OrcamentoReceitaUpdateRequest r, CancellationToken ct) { if (!EscopoValido) return EscopoFailure(); if (!await CanAsync(FinanceiroPermissoes.OrcamentoEditar, ct).ConfigureAwait(false)) return Result.Failure("403"); await _repo.AtualizarReceitaAsync(TenantId, EntidadeId, ExercicioId, id, r, UsuarioId, ct).ConfigureAwait(false); return Result.Success(); }
}

public sealed class EmpenhoService : FinanceiroServiceBase, IEmpenhoService
{
    private readonly IEmpenhoRepository _repo; private readonly IFinanceiroSequencialService _seq; private readonly ILogger<EmpenhoService> _logger;
    public EmpenhoService(IEmpenhoRepository repo, IFinanceiroSequencialService seq, ICurrentTenant tenant, ICurrentUser user, IPermissionService permissions, IAuditService audit, ILogger<EmpenhoService> logger) : base(tenant, user, permissions, audit) { _repo = repo; _seq = seq; _logger = logger; }
    public async Task<Result<PagedResult<EmpenhoResumoResponse>>> ListarAsync(EmpenhoFiltro f, CancellationToken ct) { if (!EscopoValido) return EscopoFailure<PagedResult<EmpenhoResumoResponse>>(); if (!await CanAsync(FinanceiroPermissoes.EmpenhoVisualizar, ct).ConfigureAwait(false)) return Result<PagedResult<EmpenhoResumoResponse>>.Failure("403"); return Result<PagedResult<EmpenhoResumoResponse>>.Success(await _repo.ListarAsync(TenantId, EntidadeId, ExercicioId, f, ct).ConfigureAwait(false)); }
    public async Task<Result<EmpenhoDetalheResponse>> ObterAsync(long id, CancellationToken ct) { if (!EscopoValido) return EscopoFailure<EmpenhoDetalheResponse>(); if (!await CanAsync(FinanceiroPermissoes.EmpenhoVisualizar, ct).ConfigureAwait(false)) return Result<EmpenhoDetalheResponse>.Failure("403"); var item = await _repo.ObterAsync(TenantId, EntidadeId, ExercicioId, id, ct).ConfigureAwait(false); return item is null ? Result<EmpenhoDetalheResponse>.Failure("Empenho não encontrado.") : Result<EmpenhoDetalheResponse>.Success(item); }
    public async Task<Result<long>> CriarAsync(EmpenhoCreateRequest r, string? IdempotencyKey, CancellationToken ct) { if (!EscopoValido) return EscopoFailure<long>(); if (!await CanAsync(FinanceiroPermissoes.EmpenhoCriar, ct).ConfigureAwait(false)) return Result<long>.Failure("403"); if (r.FornecedorPessoaId <= 0 || r.Itens.Count == 0 || r.Itens.Sum(i => i.Quantidade * i.ValorUnitario) <= 0m) return Result<long>.Failure("Empenho exige fornecedor, itens e valor maior que zero."); try { var ano = r.DataEmpenho.Year; var numero = await _seq.ProximoAsync(TenantId, EntidadeId, ExercicioId, ano, "empenho", "EMP", ct).ConfigureAwait(false); var op = await _repo.CriarAsync(TenantId, EntidadeId, ExercicioId, numero, ano, r, UsuarioId, IdempotencyKey, ct).ConfigureAwait(false); if (!op.Replay) await Audit.RegistrarAsync("financeiro", "EMPENHO_EMITIDO", "sigov.empenho", op.DocumentoId.ToString(System.Globalization.CultureInfo.InvariantCulture), null, r, ct).ConfigureAwait(false); return Result<long>.Success(op.DocumentoId); } catch (FinanceiroIdempotenciaConflitoException ex) { return Result<long>.Failure(ex.Message); } catch (ArgumentException ex) { return Result<long>.Failure(ex.Message); } catch (Exception ex) { _logger.LogError(ex, "Erro ao emitir empenho."); return Result<long>.Failure(ex.Message.StartsWith("Saldo disponível insuficiente") || ex.Message.StartsWith("Dotação orçamentária") ? ex.Message : "Erro ao emitir empenho. Verifique saldo disponível e exercício."); } }
    public async Task<Result> AtualizarAsync(long id, EmpenhoUpdateRequest r, CancellationToken ct) { if (!EscopoValido) return EscopoFailure(); if (!await CanAsync(FinanceiroPermissoes.EmpenhoEditar, ct).ConfigureAwait(false)) return Result.Failure("403"); try { await _repo.AtualizarAsync(TenantId, EntidadeId, ExercicioId, id, r, UsuarioId, ct).ConfigureAwait(false); return Result.Success(); } catch (Exception ex) { return Result.Failure(ex.Message.StartsWith("Empenho não encontrado") || ex.Message.StartsWith("já anulado") ? ex.Message : "Erro ao atualizar empenho."); } }
    public async Task<Result> AnularAsync(long id, AnularEmpenhoRequest r, string? IdempotencyKey, CancellationToken ct) { if (!EscopoValido) return EscopoFailure(); if (!await CanAsync(FinanceiroPermissoes.EmpenhoAnular, ct).ConfigureAwait(false)) return Result.Failure("403"); if (string.IsNullOrWhiteSpace(r.Motivo)) return Result.Failure("Motivo é obrigatório para anulação de empenho."); try { var replay = await _repo.AnularAsync(TenantId, EntidadeId, ExercicioId, id, r, UsuarioId, IdempotencyKey, ct).ConfigureAwait(false); if (!replay) await Audit.RegistrarAsync("financeiro", "EMPENHO_ANULADO", "sigov.empenho", id.ToString(System.Globalization.CultureInfo.InvariantCulture), null, r, ct).ConfigureAwait(false); return Result.Success(); } catch (FinanceiroIdempotenciaConflitoException ex) { return Result.Failure(ex.Message); } catch (ArgumentException ex) { return Result.Failure(ex.Message); } catch (Exception ex) { _logger.LogError(ex, "Erro ao anular empenho {Id}.", id); return Result.Failure(ex.Message.StartsWith("409:") || ex.Message.StartsWith("Valor excede") || ex.Message.StartsWith("Empenho não") ? ex.Message : "Erro ao anular empenho."); } }
}

public sealed class LiquidacaoService : FinanceiroServiceBase, ILiquidacaoService
{
    private readonly ILiquidacaoRepository _repo; private readonly IFinanceiroSequencialService _seq; private readonly ILogger<LiquidacaoService> _logger;
    public LiquidacaoService(ILiquidacaoRepository repo, IFinanceiroSequencialService seq, ICurrentTenant tenant, ICurrentUser user, IPermissionService permissions, IAuditService audit, ILogger<LiquidacaoService> logger) : base(tenant, user, permissions, audit) { _repo = repo; _seq = seq; _logger = logger; }
    public async Task<Result<PagedResult<LiquidacaoResponse>>> ListarAsync(LiquidacaoFiltro f, CancellationToken ct) { if (!EscopoValido) return EscopoFailure<PagedResult<LiquidacaoResponse>>(); if (!await CanAsync(FinanceiroPermissoes.LiquidacaoVisualizar, ct).ConfigureAwait(false)) return Result<PagedResult<LiquidacaoResponse>>.Failure("403"); return Result<PagedResult<LiquidacaoResponse>>.Success(await _repo.ListarAsync(TenantId, EntidadeId, ExercicioId, f, ct).ConfigureAwait(false)); }
    public async Task<Result<LiquidacaoResponse>> ObterAsync(long id, CancellationToken ct) { if (!EscopoValido) return EscopoFailure<LiquidacaoResponse>(); if (!await CanAsync(FinanceiroPermissoes.LiquidacaoVisualizar, ct).ConfigureAwait(false)) return Result<LiquidacaoResponse>.Failure("403"); var item = await _repo.ObterAsync(TenantId, EntidadeId, ExercicioId, id, ct).ConfigureAwait(false); return item is null ? Result<LiquidacaoResponse>.Failure("Liquidação não encontrada.") : Result<LiquidacaoResponse>.Success(item); }
    public async Task<Result<long>> CriarAsync(long empenhoId, LiquidacaoCreateRequest r, string? IdempotencyKey, CancellationToken ct) { if (!EscopoValido) return EscopoFailure<long>(); if (!await CanAsync(FinanceiroPermissoes.LiquidacaoCriar, ct).ConfigureAwait(false)) return Result<long>.Failure("403"); if (r.Valor <= 0m) return Result<long>.Failure("O valor da liquidação deve ser maior que zero."); try { var numero = await _seq.ProximoAsync(TenantId, EntidadeId, ExercicioId, r.DataLiquidacao.Year, "liquidacao", "LIQ", ct).ConfigureAwait(false); var op = await _repo.CriarAsync(TenantId, EntidadeId, ExercicioId, empenhoId, numero, r, UsuarioId, IdempotencyKey, ct).ConfigureAwait(false); if (!op.Replay) await Audit.RegistrarAsync("financeiro", "LIQUIDACAO_CRIADA", "sigov.liquidacao", op.DocumentoId.ToString(System.Globalization.CultureInfo.InvariantCulture), null, r, ct).ConfigureAwait(false); return Result<long>.Success(op.DocumentoId); } catch (FinanceiroIdempotenciaConflitoException ex) { return Result<long>.Failure(ex.Message); } catch (ArgumentException ex) { return Result<long>.Failure(ex.Message); } catch (Exception ex) { _logger.LogError(ex, "Erro ao criar liquidação para empenho {EmpenhoId}.", empenhoId); return Result<long>.Failure(ex.Message.StartsWith("Valor excede") || ex.Message.StartsWith("Empenho não") || ex.Message.StartsWith("Não é possível") ? ex.Message : "Erro ao registrar liquidação."); } }
    public async Task<Result> AnularAsync(long id, AnularLiquidacaoRequest r, string? IdempotencyKey, CancellationToken ct) { if (!EscopoValido) return EscopoFailure(); if (!await CanAsync(FinanceiroPermissoes.LiquidacaoAnular, ct).ConfigureAwait(false)) return Result.Failure("403"); if (string.IsNullOrWhiteSpace(r.Motivo)) return Result.Failure("Motivo é obrigatório para anulação de liquidação."); try { var replay = await _repo.AnularAsync(TenantId, EntidadeId, ExercicioId, id, r, UsuarioId, IdempotencyKey, ct).ConfigureAwait(false); if (!replay) await Audit.RegistrarAsync("financeiro", "LIQUIDACAO_ANULADA", "sigov.liquidacao", id.ToString(System.Globalization.CultureInfo.InvariantCulture), null, r, ct).ConfigureAwait(false); return Result.Success(); } catch (FinanceiroIdempotenciaConflitoException ex) { return Result.Failure(ex.Message); } catch (ArgumentException ex) { return Result.Failure(ex.Message); } catch (Exception ex) { _logger.LogError(ex, "Erro ao anular liquidação {Id}.", id); return Result.Failure(ex.Message.StartsWith("409:") || ex.Message.StartsWith("Não é possível") || ex.Message.StartsWith("Liquidação não") ? ex.Message : "Erro ao anular liquidação."); } }
}

