    public async Task<Result<long>> CriarAsync(long liquidacaoId, PagamentoCreateRequest r, string? IdempotencyKey, CancellationToken ct) { if (!EscopoValido) return EscopoFailure<long>(); if (!await CanAsync(FinanceiroPermissoes.PagamentoCriar, ct).ConfigureAwait(false)) return Result<long>.Failure("403"); if (r.Valor <= 0m) return Result<long>.Failure("O valor do pagamento deve ser maior que zero."); if (string.IsNullOrWhiteSpace(r.FormaPagamento)) return Result<long>.Failure("A forma de pagamento é obrigatória."); try { var numero = await _seq.ProximoAsync(TenantId, EntidadeId, ExercicioId, r.DataPagamento.Year, "pagamento", "PGT", ct).ConfigureAwait(false); var op = await _repo.CriarAsync(TenantId, EntidadeId, ExercicioId, liquidacaoId, numero, r, UsuarioId, IdempotencyKey, ct).ConfigureAwait(false); if (!op.Replay) await Audit.RegistrarAsync("financeiro", "PAGAMENTO_CRIADO", "sigov.pagamento", op.DocumentoId.ToString(System.Globalization.CultureInfo.InvariantCulture), null, r, ct).ConfigureAwait(false); return Result<long>.Success(op.DocumentoId); } catch (FinanceiroIdempotenciaConflitoException ex) { return Result<long>.Failure(ex.Message); } catch (ArgumentException ex) { return Result<long>.Failure(ex.Message); } catch (Exception ex) { _logger.LogError(ex, "Erro ao criar pagamento para liquidação {LiquidacaoId}.", liquidacaoId); return Result<long>.Failure(ex.Message.StartsWith("Valor excede") || ex.Message.StartsWith("Liquidação não") ? ex.Message : "Erro ao registrar pagamento."); } }
    public async Task<Result> CancelarAsync(long id, CancelarPagamentoRequest r, string? IdempotencyKey, CancellationToken ct) { if (!EscopoValido) return EscopoFailure(); if (!await CanAsync(FinanceiroPermissoes.PagamentoCancelar, ct).ConfigureAwait(false)) return Result.Failure("403"); if (string.IsNullOrWhiteSpace(r.Motivo)) return Result.Failure("Motivo é obrigatório para cancelamento de pagamento."); try { var replay = await _repo.CancelarAsync(TenantId, EntidadeId, ExercicioId, id, r, UsuarioId, IdempotencyKey, ct).ConfigureAwait(false); if (!replay) await Audit.RegistrarAsync("financeiro", "PAGAMENTO_CANCELADO", "sigov.pagamento", id.ToString(System.Globalization.CultureInfo.InvariantCulture), null, r, ct).ConfigureAwait(false); return Result.Success(); } catch (FinanceiroIdempotenciaConflitoException ex) { return Result.Failure(ex.Message); } catch (ArgumentException ex) { return Result.Failure(ex.Message); } catch (Exception ex) { _logger.LogError(ex, "Erro ao cancelar pagamento {Id}.", id); return Result.Failure(ex.Message.StartsWith("409:") || ex.Message.StartsWith("Pagamento não") ? ex.Message : "Erro ao cancelar pagamento."); } }
}

