public sealed class FinanceiroExportacaoService : FinanceiroServiceBase, IFinanceiroExportacaoService
{
    private readonly IFinanceiroExportacaoRepository _repo;
    public FinanceiroExportacaoService(IFinanceiroExportacaoRepository repo, ICurrentTenant tenant, ICurrentUser user, IPermissionService permissions, IAuditService audit) : base(tenant, user, permissions, audit) { _repo = repo; }
    public async Task<Result<byte[]>> ExportarAsync(string recurso, string formato, CancellationToken ct)
    {
        if (!EscopoValido) return EscopoFailure<byte[]>();
        if (!await CanAsync(FinanceiroPermissoes.Exportar, ct).ConfigureAwait(false)) return Result<byte[]>.Failure("403");
        await Audit.RegistrarAsync("financeiro", "EXPORTAR", $"financeiro.{recurso}", formato, null, new { recurso, formato }, ct).ConfigureAwait(false);
        var data = await _repo.ExportarAsync(TenantId, EntidadeId, ExercicioId, recurso, formato, ct).ConfigureAwait(false);
        return Result<byte[]>.Success(data);
    }
}

public sealed class FinanceiroConferenciaService : FinanceiroServiceBase, IFinanceiroConferenciaService
{
    private readonly IFinanceiroConferenciaRepository _repo; private readonly ILogger<FinanceiroConferenciaService> _logger;
    public FinanceiroConferenciaService(IFinanceiroConferenciaRepository repo, ICurrentTenant tenant, ICurrentUser user, IPermissionService permissions, IAuditService audit, ILogger<FinanceiroConferenciaService> logger) : base(tenant, user, permissions, audit) { _repo = repo; _logger = logger; }
    public async Task<Result<ConferenciaResponse>> ConferirAsync(ConferenciaFiltro filtro, CancellationToken ct)
    {
        if (!EscopoValido) return EscopoFailure<ConferenciaResponse>();
        if (!await CanAsync(FinanceiroPermissoes.ConferenciaVisualizar, ct).ConfigureAwait(false)) return Result<ConferenciaResponse>.Failure("403");
        try { return Result<ConferenciaResponse>.Success(await _repo.ConferirAsync(TenantId, EntidadeId, ExercicioId, filtro, ct).ConfigureAwait(false)); }
        catch (Exception ex) { _logger.LogError(ex, "Erro na conferência financeira."); return Result<ConferenciaResponse>.Failure("Erro na conferência financeira."); }
    }
    public async Task<Result> AjustarAsync(ConferenciaAjustarRequest request, string? IdempotencyKey, CancellationToken ct)
    {
        if (!EscopoValido) return EscopoFailure();
        if (!await CanAsync(FinanceiroPermissoes.ConferenciaAjustar, ct).ConfigureAwait(false)) return Result.Failure("403");
        if (string.IsNullOrWhiteSpace(request.Justificativa)) return Result.Failure("Justificativa é obrigatória para ajuste de conferência.");
        if (string.IsNullOrWhiteSpace(request.TipoDocumento)) return Result.Failure("Tipo de documento é obrigatório para ajuste de conferência.");
        try
        {
            // Recalcula a diferença no servidor: valores vindos da tela não são autoridade.
            var conferencia = await _repo.ConferirAsync(TenantId, EntidadeId, ExercicioId, new ConferenciaFiltro { Page = 1, PageSize = 1000 }, ct).ConfigureAwait(false);
            var item = conferencia.Itens.FirstOrDefault(i => i.DocumentoId == request.DocumentoId && string.Equals(i.TipoDocumento, request.TipoDocumento.Trim(), StringComparison.OrdinalIgnoreCase));
            if (item is null) return Result.Failure("Documento não localizado na conferência. Recarregue a tela e tente novamente.");
            decimal ajuste = item.ValorCalculado - item.ValorRegistrado;
            if (ajuste == 0m) return Result.Failure("A diferença deste documento já está zerada; não há ajuste pendente.");
            var replay = await _repo.AjustarAsync(TenantId, EntidadeId, ExercicioId, request.DocumentoId, request.TipoDocumento, ajuste, request.Justificativa, UsuarioId, IdempotencyKey, ct).ConfigureAwait(false);
            if (!replay) await Audit.RegistrarAsync("financeiro", "AJUSTE_CONFERENCIA", $"financeiro_conferencia.{request.TipoDocumento}", request.DocumentoId.ToString(System.Globalization.CultureInfo.InvariantCulture), null, new { request.DocumentoId, request.TipoDocumento, ajuste, justificativa = request.Justificativa }, ct).ConfigureAwait(false);
            return Result.Success();
        }
        catch (FinanceiroIdempotenciaConflitoException ex) { return Result.Failure(ex.Message); }
        catch (ArgumentException ex) { return Result.Failure(ex.Message); }
        catch (Exception ex) { _logger.LogError(ex, "Erro no ajuste de conferência {Id}.", request.DocumentoId); return Result.Failure("Erro no ajuste de conferência."); }
    }
}
